-- Read-only deployment assertions. A failed condition raises division by zero.
select 1 / case when md5(prosrc)='c5a5b460006822c752b662492b98ddc9' then 1 else 0 end as validator_definition_matches
from pg_proc where oid='public.spec_validate_draft_internal_v1(uuid,jsonb,text,text,text,text)'::regprocedure;
select 1 / case when not has_function_privilege('authenticated','public.spec_validate_draft_internal_v1(uuid,jsonb,text,text,text,text)','execute')
 and not has_function_privilege('anon','public.get_product_spec_references_v1(text)','execute')
 and has_function_privilege('authenticated','public.save_product_with_specs_v1(jsonb,boolean,uuid,integer,jsonb,bigint,text,text,timestamptz,jsonb)','execute') then 1 else 0 end as acl_intact;
select 1 / case when count(*)=2 then 1 else 0 end as new_definitions_present from public.spec_definitions
where tenant_id is null and key in ('chain_connector_target','chain_connector_directional');
select 1 / case when count(*)=2 and bool_and(f.constraint_rules='[]'::jsonb) then 1 else 0 end as no_mode_speed_heuristic
from public.spec_templates t join public.spec_template_fields f on f.template_id=t.id
join public.spec_definitions d on d.id=f.spec_definition_id
where t.tenant_id is null and t.key in ('chain','chain_link') and d.key='chain_speeds';
select 1 / case when count(*)=3 then 1 else 0 end as numeric_contracts_present from public.spec_definitions
where tenant_id is null and key in ('chain_outer_width_mm','link_count','chain_link_pack_qty')
 and validation_rules->>'positive'='true' and not validation_rules ? 'max' and not validation_rules ? 'min'
 and (key='chain_outer_width_mm' or validation_rules->>'integer'='true');
select 1 / case when count(*)=1 then 1 else 0 end as connector_prerequisites_present from public.spec_templates
where key='chain_link' and tenant_id is null and is_active
 and form_contract->'prerequisites'->'chain_speeds'='["chain_connector_type"]'::jsonb
 and form_contract->'prerequisites'->'chain_connector_target'='["chain_connector_type","spec_evidence_source"]'::jsonb
 and form_contract->'roles'->>'drivetrain_mode'='legacy'
 and form_contract->'roles'->>'drivetrain_declared_compatible_ecosystems'='legacy';
select 1 / case when jsonb_array_length(public.spec_validate_draft_internal_v1(id,'{"drivetrain_mode":"Derailleur","chain_speeds":["7"],"chain_width_family":"1/8"}'))>0
 and public.spec_validate_draft_internal_v1(id,'{"chain_width_family":"1/8","chain_outer_width_mm":9,"link_count":138}')='[]'::jsonb
 and jsonb_array_length(public.spec_validate_draft_internal_v1(id,'{"link_count":114.5}'))>0 then 1 else 0 end as chain_rules_work
from public.spec_templates where key='chain' and tenant_id is null;
select 1 / case when jsonb_array_length(public.spec_validate_draft_internal_v1(id,'{"chain_connector_type":"Pin","chain_link_reusable":true,"spec_evidence_source":"Envase"}'))>0
 and public.spec_validate_draft_internal_v1(id,'{"chain_connector_type":"Missing link","chain_speeds":["10"]}')='[]'::jsonb then 1 else 0 end as connector_rules_work
from public.spec_templates where key='chain_link' and tenant_id is null;
select 1 / case when count(*)=8 and bool_and(public.spec_validate_draft_internal_v1(t.id,public.spec_payload_display_internal_v1(r.fact_values),r.id,r.brand,r.model,coalesce(r.manufacturer_sku,''))='[]'::jsonb) then 1 else 0 end as reference_facts_valid
from public.product_spec_references r join public.spec_templates t on t.key=r.technical_family and t.tenant_id is null
where r.id in ('kmc-cl573r-global-20260906','kmc-cl571r-global-20260906','kmc-cl566r-global-20260906','kmc-cl559r-global-20260906','kmc-cl555r-global-20260906','kmc-cl552-global-20260906','kmc-z83-bz08ng114-eu-20260906','kmc-z7-bz07gb114-eu-20260906');
select 1 / case when count(*)=1 then 1 else 0 end as explicit_exclusion_retained
from public.product_spec_references where id='kmc-cl552-global-20260906'
 and claims @> '[{"interface":"connector_chain","excludes":["Cualquier cadena Flattop"]}]'::jsonb;

select 1 / case when md5(prosrc)='58b4b5685590ab386b5b01e404441077' and not has_function_privilege('authenticated',oid,'execute') and not has_function_privilege('anon',oid,'execute') then 1 else 0 end as private_writer_definition_matches from pg_proc where oid='public.spec_write_payload_internal_v2(uuid,uuid,jsonb,text)'::regprocedure;

-- Full normalized template metadata, including field order and every rule/source.
select 1 / case when (select coalesce(jsonb_agg(to_jsonb(a) order by a.key),'[]'::jsonb) from (select t.key, t.technical_family, t.form_contract,
       jsonb_agg(jsonb_build_object('key',d.key,'label',d.label,
         'data_type',d.data_type,'unit',d.unit,'allowed_values',d.allowed_values,
         'validation_rules',d.validation_rules,'section',f.section_key,
         'sort_order',f.sort_order,'required',f.is_required,
         'visibility_rules',f.visibility_rules,'constraint_rules',f.constraint_rules)
         order by f.sort_order,d.key) as fields
from public.spec_templates t
join public.spec_template_fields f on f.template_id=t.id
join public.spec_definitions d on d.id=f.spec_definition_id
where t.is_active and t.technical_family in ('chain','chain_link')
group by t.id order by t.key) a) = $templates$[{"key":"chain","fields":[{"key":"spec_evidence_source","unit":null,"label":"Fuente de la declaración","section":"declaration","required":false,"data_type":"text","sort_order":5,"allowed_values":[],"constraint_rules":[],"validation_rules":{},"visibility_rules":[]},{"key":"chain_directional","unit":null,"label":"Cadena direccional","section":"features","required":false,"data_type":"boolean","sort_order":10,"allowed_values":[],"constraint_rules":[],"validation_rules":{},"visibility_rules":[]},{"key":"chain_speeds","unit":null,"label":"Velocidades cadena","section":"compatibility","required":true,"data_type":"multi_select","sort_order":10,"allowed_values":["1","5","6","7","8","9","10","11","12","13"],"constraint_rules":[],"validation_rules":{},"visibility_rules":[]},{"key":"link_count","unit":"eslabones","label":"Cantidad de eslabones","section":"contents","required":false,"data_type":"number","sort_order":10,"allowed_values":["72","76","80","82","84","86","88","90","92","94","96","98","100","102","104","106","108","110","112","114","116","118","120","122","124","126","128","130","132","134","136"],"constraint_rules":[],"validation_rules":{"integer":true,"positive":true},"visibility_rules":[]},{"key":"drivetrain_mode","unit":null,"label":"Modo transmision","section":"compatibility","required":false,"data_type":"single_select","sort_order":15,"allowed_values":["Derailleur","Single speed / BMX / IGH","Desconocido / sin confirmar"],"constraint_rules":[],"validation_rules":{},"visibility_rules":[]},{"key":"chain_ebike_rated","unit":null,"label":"Apta e-bike","section":"features","required":false,"data_type":"boolean","sort_order":20,"allowed_values":[],"constraint_rules":[],"validation_rules":{},"visibility_rules":[]},{"key":"chain_width_family","unit":null,"label":"Familia ancho cadena","section":"compatibility","required":false,"data_type":"single_select","sort_order":20,"allowed_values":["1/8","3/32","11/128","Otro","Descono