select 1 / case when count(*)=1 then 1 else 0 end as clip_option_is_resolvable
from public.spec_definitions d join public.spec_definition_values v on v.spec_definition_id=d.id
where d.tenant_id is null and d.key='chain_connector_type' and v.code='clip'
 and v.label='Eslabón con clip' and d.allowed_values ? v.label;

