select 1 / case when count(*)=8 and bool_and(jsonb_build_object(
 'id',a.id,'technical_family',a.technical_family,'brand',a.brand,'model',a.model,
 'manufacturer_sku',a.manufacturer_sku,'label',a.label,
 'facts',public.spec_payload_display_internal_v1(a.fact_values),
 'sources',a.sources,'claims',a.claims,'reviewed_on',a.reviewed_on)=e.r)
 then 1 else 0 end as exact_reviewed_reference_editions
from expected e left join public.product_spec_references a on a.id=e.r->>'id';
select 1 / case when public.spec_validate_draft_internal_v1(t.id,
 public.spec_payload_display_internal_v1(r.fact_values) || '{"spec_evidence_source":"Envase revisado"}'::jsonb,
 r.id,r.brand,r.model,coalesce(r.manufacturer_sku,''))='[]'::jsonb then 1 else 0 end as independent_evidence_is_valid
from public.spec_templates t join public.product_spec_references r on r.technical_family=t.technical_family
where t.key='chain_link' and t.tenant_id is null and r.id='kmc-cl573r-global-20260906';

select 1 / case when md5(pg_get_functiondef(oid))='d87ef3bb5a913c8accbfb519cdbd0ce5' then 1 else 0 end as spec_validate_draft_internal_v1_exact_definition from pg_proc where oid='public.spec_validate_draft_internal_v1(uuid,jsonb,text,text,text,text)'::regprocedure;

select 1 / case when md5(pg_get_functiondef(oid))='9a3f9b1db3b156dbcf9e8c0448a8a945' then 1 else 0 end as spec_write_payload_internal_v2_exact_definition from pg_proc where oid='public.spec_write_payload_internal_v2(uuid,uuid,jsonb,text)'::regprocedure;
